"use server";

export type CityOption = { value: number; label: string };

/**
 * Tur filtresi şehir araması — Server Action. Route handler yerine bunu
 * kullanıyoruz: paylaşılabilir public GET URL yok, çağrı same-origin POST +
 * gizli action-id ile gelir (dışarıdan çağırmak zorlaşır). X-App-Token sunucuda
 * kalır. react-select AsyncSelect'in beklediği {value, label} biçiminde döner.
 */
export async function searchCitiesAction(q: string): Promise<CityOption[]> {
  const term = (q ?? "").trim();
  if (term.length < 2) return [];

  try {
    const res = await fetch(
      `${process.env.NEXT_PUBLIC_APIV3_URL}/locations/search?q=${encodeURIComponent(term)}`,
      {
        headers: {
          Accept: "application/json",
          "Content-Language": "en",
          "X-App-Token": process.env.APIV3_APP_TOKEN ?? "",
        },
        cache: "no-store",
      },
    );

    if (!res.ok) return [];

    const json = await res.json();
    return (json.data ?? []).map((c: any) => ({
      value: c.id,
      label: c.country ? `${c.city}, ${c.country}` : c.city,
    }));
  } catch {
    return [];
  }
}
